pub fn is_palindrome(text: Vec<char>) -> bool {
    let len = text.len();
    for i in 0..(len / 2) {
        let c1 = text[i].to_ascii_lowercase();
        let c2 = text[len - 1 - i].to_ascii_lowercase();
        if c1 != c2 {
            return false;
        }
    }
    true
}

#[cfg(test)]
mod tests {
    use super::is_palindrome;

    #[test]
    fn test_empty() {
        assert!(is_palindrome(vec![]));
    }

    #[test]
    fn test_single() {
        assert!(is_palindrome(vec!['A']));
        assert!(is_palindrome(vec!['z']));
    }

    #[test]
    fn test_even_length() {
        assert!(is_palindrome("AbBa".chars().collect()));
        assert!(!is_palindrome("Abca".chars().collect()));
    }

    #[test]
    fn test_odd_length() {
        assert!(is_palindrome("Madam".chars().collect()));
        assert!(!is_palindrome("MadamX".chars().collect()));
    }

    #[test]
    fn test_non_alpha() {
        assert!(is_palindrome("A man, a plan, a canal: Panama".chars().collect()));
        // Because we only lowercase ASCII uppercase letters and leave
        // punctuation intact, this string is not strictly a palindrome
        // under our definition.
        assert!(!is_palindrome("A man, a plan, a canal: Panama".chars().collect()));
    }
}